   157→// tryPushSessionsCommon attempts to push the sessions branch.
   158→func tryPushSessionsCommon(remote, branchName string) error {
   159→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
   160→	defer cancel()
   161→
   162→	// Use --no-verify to prevent recursive hook calls
   163→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", remote, branchName)
   164→	cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context
   165→
   166→	output, err := cmd.CombinedOutput()
   167→	if err != nil {
   168→		// Check if it's a non-fast-forward error (we can try to recover)
   169→		if strings.Contains(string(output), "non-fast-forward") ||
   170→			strings.Contains(string(output), "rejected") {
   171→			return errors.New("non-fast-forward")
   172→		}
   173→		return fmt.Errorf("push failed: %s", output)
   174→	}
   175→	return nil
   176→}
