   178→// fetchAndMergeSessionsCommon fetches remote sessions and merges into local using go-git.
   179→// Since session logs are append-only (unique cond-* directories), we just combine trees.
   180→func fetchAndMergeSessionsCommon(remote, branchName string) error {
   181→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
   182→	defer cancel()
   183→
   184→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
   185→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", remote, branchName)
   186→	fetchCmd.Stdin = nil
   187→	if output, err := fetchCmd.CombinedOutput(); err != nil {
   188→		return fmt.Errorf("fetch failed: %s", output)
   189→	}
   190→
   191→	repo, err := OpenRepository()
   192→	if err != nil {
   193→		return fmt.Errorf("failed to open git repository: %w", err)
   194→	}
   195→
   196→	// Get local branch
   197→	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
   198→	if err != nil {
   199→		return fmt.Errorf("failed to get local ref: %w", err)
   200→	}
   201→	localCommit, err := repo.CommitObject(localRef.Hash())
   202→	if err != nil {
   203→		return fmt.Errorf("failed to get local commit: %w", err)
   204→	}
   205→	localTree, err := localCommit.Tree()
   206→	if err != nil {
   207→		return fmt.Errorf("failed to get local tree: %w", err)
   208→	}
   209→
   210→	// Get remote (FETCH_HEAD)
   211→	fetchHeadRef, err := repo.Reference(plumbing.ReferenceName("FETCH_HEAD"), true)
   212→	if err != nil {
   213→		return fmt.Errorf("failed to get FETCH_HEAD: %w", err)
   214→	}
   215→	remoteCommit, err := repo.CommitObject(fetchHeadRef.Hash())
   216→	if err != nil {
   217→		return fmt.Errorf("failed to get remote commit: %w", err)
   218→	}
   219→	remoteTree, err := remoteCommit.Tree()
   220→	if err != nil {
   221→		return fmt.Errorf("failed to get remote tree: %w", err)
   222→	}
   223→
   224→	// Flatten both trees and combine entries
   225→	// Session logs have unique cond-* directories, so no conflicts expected
   226→	entries := make(map[string]object.TreeEntry)
   227→	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
   228→		return fmt.Errorf("failed to flatten local tree: %w", err)
   229→	}
   230→	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
   231→		return fmt.Errorf("failed to flatten remote tree: %w", err)
   232→	}
   233→
   234→	// Build merged tree
   235→	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
   236→	if err != nil {
   237→		return fmt.Errorf("failed to build merged tree: %w", err)
   238→	}
   239→
   240→	// Create merge commit with both parents
   241→	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
   242→		[]plumbing.Hash{localRef.Hash(), fetchHeadRef.Hash()},
   243→		"Merge remote session logs")
   244→	if err != nil {
   245→		return fmt.Errorf("failed to create merge commit: %w", err)
   246→	}
   247→
   248→	// Update branch ref
   249→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), mergeCommitHash)
   250→	if err := repo.Storer.SetReference(newRef); err != nil {
   251→		return fmt.Errorf("failed to update branch ref: %w", err)
   252→	}
   253→
   254→	return nil
   255→}
