   257→// createMergeCommitCommon creates a merge commit with multiple parents.
   258→func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
   259→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   260→	now := time.Now()
   261→	sig := object.Signature{
   262→		Name:  authorName,
   263→		Email: authorEmail,
   264→		When:  now,
   265→	}
   266→
   267→	commit := &object.Commit{
   268→		TreeHash:     treeHash,
   269→		ParentHashes: parents,
   270→		Author:       sig,
   271→		Committer:    sig,
   272→		Message:      message,
   273→	}
   274→
   275→	obj := repo.Storer.NewEncodedObject()
   276→	if err := commit.Encode(obj); err != nil {
   277→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
   278→	}
   279→
   280→	hash, err := repo.Storer.SetEncodedObject(obj)
   281→	if err != nil {
   282→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
   283→	}
   284→
   285→	return hash, nil
   286→}
